pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address deployer) public {
        vm.assume(deployer != address(0));
        address expectedOwner = deployer;
        vm.prank(deployer);
        C newC = new C(address(this), address(this));
        assertTrue(newC.owner() == expectedOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner() && newOwner != address(0) && newOwner != c.owner() && caller != address(this));
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            assertTrue(c.owner() == newOwner);
        } catch {
            assertTrue(c.owner() != newOwner);
        }
    }
}

